using System;using System.IO;using System.Reflection;using UnityEngine;namespace Exoduser.UnityPort.Tools {internal static class NativeQaAssembly {internal static string FilePath(Assembly assembly){string file=assembly.Location;if(!string.IsNullOrEmpty(file)&&File.Exists(file))return file;file=Path.Combine(Application.dataPath,"Managed",assembly.GetName().Name+".dll");if(!File.Exists(file))throw new FileNotFoundException("Actual Player assembly is required",file);return file;}}}
